from pathlib import Path
from html import escape as e
import json

def render(data,root,out):
 css=(root/'scripts/editorial.css').read_text();js=(root/'scripts/editorial.js').read_text();items=[i for i in data['items'] if not i.get('placeholder')];cats=sorted(data['categories'],key=lambda c:c.get('order',0));labels={c['id']:c for c in cats}
 def tr(tag,zh,en,attrs=''):return f'<{tag} data-zh="{e(zh,quote=True)}" data-en="{e(en,quote=True)}" {attrs}>{e(zh)}</{tag}>'
 def label(n,title,note=''):return f'<div class="section-label"><span>{n} / 05 &nbsp; {title}</span><span>{note}</span></div>'
 def img(i):
  matches=list((out/'assets/thumbs').glob('article-'+i['id']+'-*.webp'))
  return '/'+str(matches[0].relative_to(out))
 nav=''.join(f'<a href="#{ident}">{title}</a>' for ident,title in [('about','ABOUT'),('work','WORK'),('writing','WRITING'),('now','NOW'),('contact','CONTACT')])
 workids=['parallel-universe','night-video','ai-workflow','website-build'];works=[next(i for i in items if i['id']==id) for id in workids];worktitles=[('平行宇宙报社','Parallel Universe Press','EDITORIAL / AI EXPERIMENT'),('追夜','Chasing the Night','VISUAL / FIVE CITIES'),('把想法做出来','From Idea to Something Real','WORKFLOW / AI'),('这座数字花园','This Digital Garden','WEB / PERSONAL SPACE')]
 workrows=[]
 for n,(i,(zh,en,meta)) in enumerate(zip(works,worktitles),1):
  workrows.append(f'<a class="work-row" href="/posts/{i["id"]}.html" data-image="{img(i)}"><small>0{n}</small><div>{tr("h3",zh,en)}<p>{meta}</p></div><span class="arrow" aria-hidden="true">↗</span></a>')
 filters=tr('button','全部','ALL','type="button" data-filter="all" aria-pressed="true"')+''.join(tr('button',c['zh'],c['en'],f'type="button" data-filter="{c["id"]}" aria-pressed="false"') for c in cats)
 articles=[]
 for n,i in enumerate(items,1):
  cat=labels[i['category']];keywords=i['title']['zh']+' '+i['title']['en']+' '+i['summary']['zh']+' '+cat['zh']
  articles.append(f'<a class="article-row" href="/posts/{i["id"]}.html" data-category="{i["category"]}" data-search="{e(keywords,quote=True)}"><span class="num">{n:02d}</span><img src="{img(i)}" loading="lazy" width="480" height="320" alt="{e(i["title"]["zh"])}">{tr("h3",i["title"]["zh"],i["title"]["en"])}{tr("span",cat["zh"],cat["en"],"class=\"cat\"")}<time>{i.get("date","")}</time><span class="row-arrow" aria-hidden="true">↗</span>{tr("p",i["summary"]["zh"],i["summary"]["en"],"class=\"row-summary\"")}</a>')
 dots=''.join(f'<a href="#{ident}" aria-label="{title}"><span>{title}</span></a>' for ident,title in [('home','HOME'),('about','ABOUT'),('work','WORK'),('writing','WRITING'),('now','NOW'),('contact','CONTACT')])
 html=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#fafaf7"><meta name="description" content="{e(data['site']['description']['zh'])}"><title>Young · 数字花园 / Digital Garden</title><link rel="icon" href="/favicon.svg" type="image/svg+xml"><style>{css}</style></head><body><a class="skip" href="#about">跳到正文</a><header class="masthead"><a href="#home" class="wordmark" aria-label="Young 首页">YOUNG<span style="color:#80975d">.</span></a><nav class="mainnav" id="mainnav" aria-label="主导航">{nav}</nav><div class="utility"><button id="language" type="button" aria-label="切换中英文">EN / 中</button><button id="theme" class="theme" type="button" aria-label="切换深浅主题" aria-pressed="false"></button><button id="menu" class="menu-button" type="button" aria-label="打开导航" aria-controls="mainnav" aria-expanded="false">☰</button></div></header><nav class="section-nav" aria-label="页面章节">{dots}</nav><div class="edge-line" aria-hidden="true"><div class="edge-progress"></div></div><main>
<section class="hero" id="home"><div class="hero-title"><p class="overline">A PERSONAL SPACE, ALWAYS IN PROGRESS.</p><h1 aria-label="Young"><span>Y</span><span>O</span><span>U</span><span>N</span><span>G</span></h1><div class="hero-subtitle">DIGITAL GARDEN</div></div><div class="hero-note">ENGINEERING. CURIOSITY. EVERYDAY LIFE.<br>{tr('span','工程、好奇心，和生活里的小事。','Learning, making, and figuring things out.')}</div><a href="#about" class="scroll-cue">SCROLL TO EXPLORE ↓</a><div class="hero-location"><i></i>KEEP LEARNING / KEEP MAKING</div></section>
<section class="section" id="about">{label('01','ABOUT','一点关于我')}<div class="about-grid"><div class="reveal">{tr('h2','在学习，也在生长。','Learning. Still growing.','class="about-heading"')}<p class="about-note">YOUNG / ELECTRICAL ENGINEERING<br>A GARDEN OF UNFINISHED THOUGHTS.</p><div class="about-tags"><span>ENGINEERING</span><span>AI & WEB</span><span>RUNNING</span><span>F1</span></div></div><div class="reveal">{tr('p',data['site']['about']['zh'],data['site']['about']['en'],'class="about-text"')}{tr('p',data['site']['description']['zh'],data['site']['description']['en'])}<a class="inline-link" href="/posts/garden-origin.html">{tr('span','我为什么弄这个小站','Why I started this garden')} &nbsp; ↗</a></div></div></section>
<section class="section" id="work"><span id="explore" class="section-alias" aria-hidden="true"></span>{label('02','WORK','把想法做出来')}<div class="reveal"><h2 class="section-title">SELECTED<br>EXPERIMENTS.</h2>{tr('p','一些做过的东西，也包括还在折腾的想法。','Things I have made, and ideas I am still working through.','class="section-intro"')}</div><div class="work-layout"><div class="work-list reveal">{''.join(workrows)}</div><div class="work-preview reveal"><a id="project-preview" href="/posts/parallel-universe.html"><div class="preview-frame"><img id="project-image" src="{img(works[0])}" width="480" height="320" alt="平行宇宙报社"></div></a><div class="preview-caption"><span id="project-caption">平行宇宙报社</span><span>EXPLORE THE PROCESS ↗</span></div></div></div>{tr('p','把鼠标移到项目上，看看它的另一面。','Hover a project. Follow the process.','class="work-caption"')}</section>
<section class="section" id="writing"><span id="collection" class="section-alias" aria-hidden="true"></span>{label('03','WRITING','记录正在发生的事')}<div class="writing-top reveal"><h2 class="section-title">FIELD NOTES.</h2><div class="view-switch" role="group" aria-label="文章展示方式"><button type="button" data-view="list" aria-pressed="true">LIST</button><button type="button" data-view="archive" aria-pressed="false">ARCHIVE</button></div></div>{tr('p','算错的题、修过的电脑，和还没想明白的事。','Wrong answers, repaired computers, and open questions.','class="section-intro"')}<div class="tools"><div class="filters" role="group" aria-label="筛选文章">{filters}</div><label class="searchbox"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="搜索记录 / SEARCH" aria-label="搜索文章标题及摘要"></label></div><div class="article-list" id="article-list">{''.join(articles)}</div>{tr('p','没有找到匹配的文章，换个关键词试试。','No matching notes. Try another search.','class="empty" id="empty" hidden')}<p class="count" id="result-count" aria-live="polite">19 篇记录</p></section>
<section class="section" id="now">{label('04','NOW','此刻的切片')}<h2 class="section-title reveal">IN PROGRESS.</h2><div class="now-grid"><div class="reveal">{tr('p','课本之外，还有很多值得认真折腾的事。','There is a lot worth exploring beyond the textbook.','class="now-text"')}{tr('p','这里是学习、创作和日常交汇的地方。没有标准答案，先留下过程。','A place where learning, making, and daily life meet. Keeping the process, not just the result.','class="section-intro"')}</div><div class="now-list reveal"><div>{tr('strong','电气工程','Electrical engineering')}<small>01 / LEARNING</small></div><div>{tr('strong','AI 与网站','AI & the web')}<small>02 / MAKING</small></div><div>{tr('strong','电脑与服务器','Computers & servers')}<small>03 / TINKERING</small></div><div>{tr('strong','跑步、电影与 F1','Running, films & F1')}<small>04 / LIVING</small></div></div></div><div class="marquee" aria-hidden="true"><div>{('LEARN · MAKE · BREAK · REPAIR · WRITE · RUN · REPEAT · '*4)}</div></div></section>
<section class="section contact" id="contact">{label('05','CONTACT','保持联系')}<a class="contact-heading reveal" href="mailto:{e(data['site']['contact']['zh'])}">SAY HELLO<span class="arrow">↗</span></a><div class="contact-links"><a href="mailto:{e(data['site']['contact']['zh'])}">EMAIL ↗</a><a href="https://github.com/YOUNG7788-WEB" target="_blank" rel="noopener noreferrer">GITHUB ↗</a><a href="/lite.html">{tr('span','省流阅读','TEXT ONLY')} ↗</a></div>{tr('p','如果你也在学习、折腾，或者只是想聊聊，欢迎写信。','Learning something, making something, or just want to talk? Drop me a line.','class="contact-note"')}<p class="contact-note">{e(data['site']['contact']['zh'])}</p><footer class="footer"><span>© 2026 YOUNG · DIGITAL GARDEN</span><span>ALWAYS A WORK IN PROGRESS.</span><a href="#home" aria-label="返回顶部">↑</a></footer></section></main><script>{js}</script></body></html>'''
 (out/'index.html').write_text(html,encoding='utf-8')
 (out/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="#141612"/><text x="32" y="47" text-anchor="middle" fill="#c9dc9b" font-family="Arial" font-weight="900" font-size="46">Y</text></svg>')
